parameters.jsCode:
const userText = $('Normalize Input').first().json.user_text.toLowerCase();
const menuItems = $input.all();
let totalPrice = 0;
const validatedItems = [];

for (const item of menuItems) {
  const row = item.json;
  if (!row.is_available) continue;

  // Basic word-number or digit matching for quantities (defaults to 1 if unspecified)
  const regex = new RegExp(`(\\d+)\\s*(?:x|of)?\\s*${row.title_or_question.toLowerCase()}`, 'i');
  const match = userText.match(regex);
  const quantity = match ? parseInt(match[1], 10) : 1;

  const itemTotal = parseFloat(row.price) * quantity;
  totalPrice += itemTotal;

  validatedItems.push({
    id: row.id,
    name: row.title_or_question,
    quantity: quantity,
    unit_price: row.price,
    subtotal: itemTotal
  });
}

return [{
  json: {
    items_summary: validatedItems.map(i => `${i.quantity}x ${i.name}`).join(', '),
    total_price: totalPrice.toFixed(2),
    is_valid_order: validatedItems.length > 0
  }
}];

